import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageSubjects() {
  const [subjects, setSubjects] = useState([]);
  const [subjectName, setSubjectName] = useState('');

  const fetchSubjects = () => {
    axios.get('http://localhost:8081/api/view-subjects')
      .then(res => setSubjects(res.data))
      .catch(err => console.error("Error fetching subjects:", err));
  };

  useEffect(() => { fetchSubjects(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/add-subject', { subject_name: subjectName })
      .then(() => {
        fetchSubjects();
        setSubjectName('');
      })
      .catch(err => alert("Error adding subject!"));
  };

  const handleDelete = (id) => {
    if (window.confirm("Are you sure you want to delete this subject?")) {
      axios.delete(`http://localhost:8081/api/delete-subject/${id}`)
        .then(() => fetchSubjects());
    }
  };

  return (
    <div style={{ padding: '30px', fontFamily: 'sans-serif', backgroundColor: '#fff', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
      <h2 style={{ color: '#15803d', marginBottom: '25px' }}>📚 Manage Subjects</h2>
      
      <form onSubmit={handleSubmit} style={{ marginBottom: '30px', display: 'flex', gap: '15px' }}>
        <input 
          type="text" 
          placeholder="Enter new subject name..." 
          value={subjectName} 
          onChange={(e) => setSubjectName(e.target.value)} 
          required 
          style={{ padding: '12px', width: '350px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none' }}
        />
        <button type="submit" style={{ padding: '10px 25px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>+ Add Subject</button>
      </form>

      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ backgroundColor: '#f8fafc', textAlign: 'left' }}>
            <th style={{ padding: '15px', borderBottom: '2px solid #e2e8f0', color: '#64748b' }}>ID</th>
            <th style={{ padding: '15px', borderBottom: '2px solid #e2e8f0', color: '#64748b' }}>Subject Name</th>
            <th style={{ padding: '15px', borderBottom: '2px solid #e2e8f0', color: '#64748b', textAlign: 'center' }}>Actions</th>
          </tr>
        </thead>
        <tbody>
          {subjects.map(s => (
            <tr key={s.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
              <td style={{ padding: '15px', fontWeight: 'bold', color: '#475569' }}>{s.id}</td>
              <td style={{ padding: '15px', fontSize: '16px', color: '#1e293b' }}>{s.subject_name}</td>
              <td style={{ padding: '15px', textAlign: 'center' }}>
                <button onClick={() => handleDelete(s.id)} style={{ padding: '6px 12px', backgroundColor: '#fee2e2', color: '#dc2626', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
